args.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT ?award ?awardLabel WHERE {
  ?award rdfs:label ?awardLabel ;
         dbo:abstract ?abs .
  FILTER(lang(?awardLabel) = "en" && lang(?abs) = "en")
  FILTER(CONTAINS(LCASE(?awardLabel), "academy award"))
  FILTER(CONTAINS(LCASE(?abs), "jamie foxx"))
} LIMIT 50

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?performer ?performerLabel ?award ?awardLabel WHERE {
  dbr:You_Changed_Me dbo:artist ?performer .
  OPTIONAL { ?performer rdfs:label ?performerLabel . FILTER(lang(?performerLabel) = "en") }

  {
    ?performer dbo:award ?award .
  }
  UNION
  {
    ?performer dbp:award ?award .
  }
  UNION
  {
    ?performer dbp:awards ?award .
  }
  UNION
  {
    ?award dbp:recipient ?performer .
  }
  UNION
  {
    ?award dbp:winner ?performer .
  }
  UNION
  {
    ?award dbp:awardWinner ?performer .
  }
  UNION
  {
    ?award dbo:recipient ?performer .
  }
  UNION
  {
    ?award dbo:award ?performer .
  }
  OPTIONAL { ?award rdfs:label ?awardLabel . FILTER(lang(?awardLabel) = "en") }
} LIMIT 100

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dc: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?performer ?perfLabel ?awardCategory ?awardLabel WHERE {
  dbr:You_Changed_Me dbo:artist ?performer .
  OPTIONAL { ?performer rdfs:label ?perfLabel . FILTER(lang(?perfLabel) = "en") }
  ?performer dc:subject ?awardCategory .
  OPTIONAL { ?awardCategory rdfs:label ?awardLabel . FILTER(lang(?awardLabel) = "en") }
  FILTER(CONTAINS(LCASE(STR(?awardCategory)), "grammy") || (BOUND(?awardLabel) && CONTAINS(LCASE(?awardLabel), "grammy")))
} LIMIT 50

